function auditR44SizingAndExits(result){
 let wallet=10000,maxBudgetError=0,maxQtyError=0; const exits={stop:0,deadline:0,terminal:0,stop_worse_fill:0};let maxHold=0,minRemaining=Infinity;
 for(const t of [...result.records].sort((a,b)=>a.opened_at-b.opened_at)){
  const o=t.opening_log,p=t.plan_log,dir=t.side==="long"?1:-1;
  const budget=.01*wallet,unit=o.distance+.00045*(t.entry+o.stop)+.001*t.entry;
  const q=Math.floor(Math.min(budget/unit,4.4*.5*wallet/t.entry,.90*.5*wallet*3/(t.entry*(1+.00045*3)))/.001)*.001;
  const be=Math.abs(o.risk_budget-budget),qe=Math.abs(t.qty-q);maxBudgetError=Math.max(be,maxBudgetError);maxQtyError=Math.max(qe,maxQtyError);
  if(be>1e-6||qe>1e-8)throw Error("wallet sizing");
  if(!(Number.isFinite(o.anchor)&&Number.isFinite(o.deadline)&&o.deadline-o.anchor===86400000&&t.opened_at>o.anchor+28800000&&t.opened_at<o.deadline))throw Error("entry range clock");
  if(t.closed_at>o.deadline)throw Error("position beyond deadline");
  const protective=t.orders.filter(z=>z.reduce_only&&z.type==="STOP"&&z.created_at===t.opened_at);if(protective.length!==1||Math.abs(protective[0].price-o.stop)>1e-6||Math.abs(Math.abs(protective[0].qty)-t.qty)>1e-8)throw Error("initial native protective stop");
  const x=t.orders.filter(x=>x.reduce_only&&x.status==="EXECUTED")[0],hold=t.closed_at-t.opened_at;
  if(x.type==="STOP"){if(!Number.isFinite(x.price)||dir*(x.price-o.stop)>1e-6||x.submitted_via!=="stop-loss")throw Error("native STOP semantics");if(Math.abs(x.price-o.stop)>1e-6)exits.stop_worse_fill++;exits.stop++;}
  else if(t.closed_at===1767225600000&&x.type==="MARKET"){exits.terminal++;}
  else if(x.type==="MARKET"&&t.closed_at===o.deadline){exits.deadline++;}
  else throw Error("unclassified exit "+JSON.stringify(x));
  maxHold=Math.max(maxHold,hold/3600000);minRemaining=Math.min(minRemaining,(o.deadline-t.opened_at)/60000);wallet+=t.net;
 }
 if(Math.abs(wallet-result.finish)>1e-6||maxHold>=16)throw Error("wallet final or max hold");
 return {status:"PASS",trades:result.N,maxBudgetError,maxQtyError,maxHold,minRemaining,exits};
}
